import {renderEnergyWeekly} from './energy-weekly.mjs';
import {createRepairSpacing,repairSpacingRows} from './energy-repair-spacing.mjs';
import {renderEnergyCalendar} from './energy-calendar-ui.mjs';
import {createRepairHistory,repairPriorities} from './energy-repair-history.mjs';
import {createEnergyExamHistory,energyExamScore,energyMastery} from './energy-exam-history.mjs';
import {createEnergyResults} from './energy-results.mjs';
import {createEnergySpacing} from './energy-spacing.mjs';
import {createEnergyExam,finishEnergyExam,examCorrect} from './energy-exam-model.mjs';
import {createExamRepair,applyExamRepair} from './energy-exam-repair.mjs';
import {energyFaultScore,faultCatalog} from './energy-faults.mjs';
let storage;try{storage=localStorage;}catch{}const results=createEnergyResults(storage),spacing=createEnergySpacing(storage),key='mecanica.energy-exam.v1';const archive=createEnergyExamHistory(storage);const repairHistory=createRepairHistory(storage,results.all());const repairSpacing=createRepairSpacing(storage);repairSpacing.sync(repairSpacingRows(repairHistory.all()));let inspected=null,retry=null,repair=null;const repairs=new Map();const shown=()=>inspected||exam;let exam=null,warning='',selected=0,ready=false,reviewRepaired=false;
try{const s=JSON.parse(storage.getItem(key)||'null');if(s&&['active','finished'].includes(s.status)&&Array.isArray(s.cases)&&s.cases.length===3&&s.cases.every(c=>faultCatalog[c.lab]&&Array.isArray(c.faults)&&c.faults.length&&c.faults.every(f=>faultCatalog[c.lab].some(x=>x.id===f)))&&Array.isArray(s.answers)&&s.answers.length<=3&&s.answers.every(Array.isArray))exam=s;}catch{warning='No se pudo recuperar el intento anterior.';}
const panel=document.querySelector('#exam'),frame=document.querySelector('#lab'),names={transformload:'Transformador',opamp:'Operacional',relief:'Hidráulica'};
function persist(){try{storage.setItem(key,JSON.stringify(exam));}catch{warning='El examen solo se conserva en esta sesión.';}}
function send(){if(ready){const c=repair?.state||shown().cases[selected];frame.contentWindow.postMessage({type:'energy-exam-case',faults:c.faults,level:c.level,repaired:reviewRepaired,...(repair?{repairedIds:repair.state.repairedIds}:{})},location.origin);}}
function view(i,repaired=false){selected=i;reviewRepaired=repaired;const url='index.html?id='+(repair?.state||shown().cases[i]).lab+'&exam=1';frame.hidden=false;if(frame.getAttribute('src')===url){send();}else{ready=false;frame.src=url;}render();}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;if(e.data?.type==='energy-exam-ready'){ready=true;send();render();}if(e.data?.type==='concept-height'&&Number.isFinite(e.data.height))frame.style.height=Math.min(14000,Math.max(700,e.data.height))+'px';});
function render(){renderArchive();renderRepairHistory();panel.replaceChildren();const el=(tag,text,parent=panel)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const button=(text,fn)=>{const b=el('button',text);b.onclick=fn;return b;};if(warning||results.warning())el('p',warning||results.warning());
if(repair){renderRepair(el,button);return;}
if(retry){renderRetry(el,button);return;}
if(inspected)button('Volver al examen actual',()=>{inspected=null;if(exam)view(exam.status==='active'?exam.answers.length:0);else{frame.hidden=true;render();}});
if(!exam&&!inspected){el('p','Examen adaptativo: prioriza errores anteriores, explora causas menos practicadas y aumenta la dificultad con aciertos consistentes. Las causas y la corrección se revelan al terminar.');button('Comenzar examen',()=>{exam=createEnergyExam(results.all(),Math.random,archive.all());persist();view(0);});return;}
if(!inspected&&exam.status==='active'){const i=exam.answers.length;if(i>=3){finish();return;}el('h2','Caso '+(i+1)+' / 3 · '+names[exam.cases[i].lab]);el('p','A es la referencia normal; B tiene una o varias averías. Observa varios instantes antes de responder.');const form=el('form','');for(const f of faultCatalog[exam.cases[i].lab]){const label=el('label','',form),input=el('input','',label);input.type='checkbox';input.value=f.id;label.append(document.createTextNode(f.label));}const submit=el('button',ready?'Guardar respuesta y continuar':'Cargando bancos…',form);submit.disabled=!ready;form.onsubmit=e=>{e.preventDefault();const answer=[...form.querySelectorAll('input:checked')].map(x=>x.value);if(!answer.length){el('p','Selecciona al menos una causa.');return;}exam.answers.push(answer);persist();if(exam.answers.length===3)finish();else view(exam.answers.length);};return;}
const reviewed=shown();const good=reviewed.cases.filter((c,i)=>examCorrect(c,reviewed.answers[i])).length;el('h2','Resultado: '+Math.round(good/3*100)+'/100 · '+good+'/3 casos');el('p','Cada caso vale 100 si identificaste exactamente todas las causas, o 0 si omitiste o añadiste alguna. Los errores y niveles ajustan tus repasos; solo los casos correctos cuentan para la meta diaria.');
reviewed.cases.forEach((c,i)=>{const card=el('article','');card.className='exam-result';const label=f=>faultCatalog[c.lab].find(x=>x.id===f)?.label||f;el('h3',names[c.lab]+' · '+(examCorrect(c,reviewed.answers[i])?'Correcto':'Para repasar'),card);el('p',c.adaptation||'Caso de un examen anterior.',card);el('p','Elegiste: '+reviewed.answers[i].map(label).join(', ')+'. Causas reales: '+c.faults.map(label).join(', ')+'.',card);const missing=c.faults.filter(f=>!reviewed.answers[i].includes(f)),extra=reviewed.answers[i].filter(f=>!c.faults.includes(f));if(missing.length)el('p','Te faltó identificar: '+missing.map(label).join(', ')+'.',card);if(extra.length)el('p','Señalaste sin evidencia en este caso: '+extra.map(label).join(', ')+'.',card);el('p',c.faults.map(f=>faultCatalog[c.lab].find(x=>x.id===f).explain).join(' '),card);for(const [text,repaired]of [['Comparar con avería',false],['Ver ambos reparados',true]]){const b=el('button',text,card);b.onclick=()=>view(i,repaired);}if(!examCorrect(c,reviewed.answers[i])){const b=el('button','Repetir este caso fallado',card);b.dataset.retryCase=i;b.onclick=()=>{retry={index:i,errors:0,done:false,feedback:'',recordId:crypto.randomUUID()};view(i);};}const rb=el('button','Taller de reparación',card);rb.dataset.repairCase=i;rb.onclick=()=>{const key=reviewed.id+':'+i;if(!repairs.has(key))repairs.set(key,createExamRepair(reviewed,i));repair=repairs.get(key);view(i);};const a=el('a','Repasar este laboratorio ↗',card);a.href='index.html?id='+c.lab+'&review='+c.faults[0];});const active=reviewed.cases[selected];el('h3','Revisión en los bancos · '+names[active.lab]);el('p',reviewRepaired?'Ambos bancos reparados: compara cómo vuelven a coincidir las magnitudes.':'A conserva la referencia normal. B reproduce todas las causas de este caso con el mismo reloj.');for(const f of active.faults){const cause=faultCatalog[active.lab].find(x=>x.id===f);el('p',cause.label+': '+cause.explain);}if(active.level==='intermittent')el('p','Observa varios segundos: la señal puede coincidir temporalmente y volver a fallar. Usa pausa y velocidad lenta en los bancos.');button('Caso anterior',()=>view((selected+2)%3));button('Siguiente caso',()=>view((selected+1)%3));button('Nuevo examen adaptativo',()=>{inspected=null;exam=createEnergyExam(results.all(),Math.random,archive.all());persist();view(0);});}
function renderRepair(el,button){
 const s=repair.state;
 el('h2','Taller de reparación · '+names[s.lab]);
 el('p','Elige qué corregir primero. A mantiene la referencia normal; B muestra las averías que siguen activas. Las intervenciones representan reparaciones con el equipo aislado.');
 el('p','Puntuación: '+energyFaultScore(s)+'/100 · Errores: '+s.errors+' · Pistas: '+s.hints);
 el('p','−15 por intervención innecesaria o comprobación prematura; −10 por pista. Mínimo 0. No cambia la nota del examen.');
 const feedback=el('p',s.log.at(-1)||'Observa las magnitudes de ambos bancos antes de intervenir.');feedback.setAttribute('role','status');
 const action=(kind,choice)=>{applyExamRepair(repair,kind,choice);if(s.done){repairHistory.save(s);repairSpacing.sync(repairSpacingRows(repairHistory.all()));results.save(s);spacing.sync(results.all());}send();render();};
 for(const f of faultCatalog[s.lab]){const b=button((s.repairedIds.includes(f.id)?'✓ Aplicada · ':'')+f.repair,()=>action('repair',f.id));b.dataset.repairFault=f.id;b.disabled=!ready||s.done;}
 const hint=button('Pedir pista (−10)',()=>action('hint'));hint.dataset.repairHint='';hint.disabled=!ready||s.done;
 const verify=button('Comprobar todas las averías',()=>action('verify'));verify.dataset.repairVerify='';verify.disabled=!ready||s.done;
 if(s.done)el('p','Reparación completada y guardada como práctica independiente. Ambos bancos coinciden en las 101 muestras de verificación.');
 if(s.log.length){const details=el('details','');const title=document.createElement('summary');title.textContent='Bitácora de intervenciones';details.append(title);for(const entry of s.log)el('p',entry,details);}
 button('Volver a la revisión',()=>{repair=null;if(shown())view(shown().status==='active'?shown().answers.length:0);else{frame.hidden=true;render();}});
 el('p','Los resultados completos se guardan en este navegador. Las prácticas en curso no se recuperan tras recargar. Al salir, la revisión muestra el caso original.');
}
function renderRepairHistory(){
 let host=document.querySelector('#repairHistory');if(!host){host=document.createElement('section');host.id='repairHistory';panel.before(host);}host.replaceChildren();
 const add=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;};
 add('h2','Tu historial de reparaciones');const examLink=add('a','Examen semanal de reparación →');examLink.href='repair-exam.html';add('p','Hasta 100 talleres completados, guardados en este navegador. La puntuación es independiente del examen.');if(repairHistory.warning())add('p',repairHistory.warning());
 const rows=repairHistory.all();
 const launch=(c,target)=>{const source={id:'practice:'+crypto.randomUUID(),status:'finished',cases:[c]};repair=createExamRepair(source,0);repair.state.reviewTarget=target||null;retry=null;view(0);panel.scrollIntoView({block:'start'});};
 renderEnergyWeekly(host,{rows:repairSpacingRows(rows),store:repairSpacing,plan:repairPriorities(rows),kind:'repair',begin:item=>launch({lab:item.lab,level:item.level,faults:[item.fault]},item.fault)});
 renderEnergyCalendar(host,{onGoalChange:render,store:repairSpacing,rows,plan:repairPriorities(rows),kind:'repair',begin:item=>launch({lab:item.lab,level:item.level,faults:[item.fault]},item.fault)});
 if(!rows.length)add('p','Completa un taller para ver tus puntuaciones y dificultades. También puedes empezar con un reto personalizado.');
 const list=add('details','');const summary=document.createElement('summary');summary.textContent='Comparar puntuaciones · '+rows.length+' reparaciones';list.append(summary);
 for(let i=rows.length-1;i>=0;i--){const r=rows[i],prev=rows.slice(0,i).reverse().find(x=>x.lab===r.lab&&x.level===r.level);const p=document.createElement('p');p.textContent=new Date(r.date).toLocaleString('es-CO')+' · '+names[r.lab]+' · '+({basic:'básico',combined:'combinado',intermittent:'intermitente'}[r.level])+' · '+r.score+'/100'+(prev?' · '+(r.score-prev.score)+' puntos respecto al anterior del mismo laboratorio y nivel':' · Primera referencia en este nivel');p.textContent+=' · '+r.faults.map(f=>faultCatalog[r.lab].find(x=>x.id===f).label).join(' + ');list.append(p);const meter=document.createElement('meter');meter.max=100;meter.value=r.score;meter.setAttribute('aria-label','Puntuación '+r.score);list.append(meter);const b=document.createElement('button');b.textContent='Repetir estas averías';b.dataset.repeatRepair=r.id;b.onclick=()=>launch(r);list.append(b);}
 add('h3','Qué practicar ahora');add('p','Prioridad según errores y pistas de las últimas tres prácticas por causa. Una comprobación prematura puede afectar varias causas pendientes; indica dificultad en ese contexto, no una medida exacta de dominio.');
 for(const item of repairPriorities(rows)){add('p',names[item.lab]+' · '+item.label+' · '+item.n+' prácticas · '+item.errors+' errores y '+item.hints+' pistas recientes. '+item.reason);const b=add('button','Practicar · '+(item.level==='basic'?'estable':'intermitente'));b.dataset.practiceRepair=item.lab+':'+item.fault;b.onclick=()=>launch({lab:item.lab,level:item.level,faults:[item.fault]},item.fault);}
}
function renderRetry(el,button){const c=shown().cases[retry.index];el('h2','Repite el caso · '+names[c.lab]);el('p','Mismas causas y nivel que en el examen original. Tu nueva práctica no sustituye aquella nota.');el('p',retry.feedback);if(!retry.done){const form=el('form','');for(const f of faultCatalog[c.lab]){const label=el('label','',form),input=el('input','',label);input.type='checkbox';input.value=f.id;label.append(document.createTextNode(f.label));}const b=el('button','Comprobar',form);b.disabled=!ready;form.onsubmit=e=>{e.preventDefault();const answer=[...form.querySelectorAll('input:checked')].map(x=>x.value);if(!answer.length)return;if(examCorrect(c,answer)){retry.done=true;retry.feedback='Correcto. Todas las causas identificadas; repaso guardado sin modificar el examen.';results.save({...c,id:retry.recordId,done:true,finishedAt:new Date().toISOString(),errors:retry.errors,hints:0,events:Array.from({length:retry.errors},()=>({action:'retry',wrong:true,targets:c.faults})),sourceExam:shown().id,sourceCase:retry.index});spacing.sync(results.all());}else{retry.errors++;retry.feedback='Todavía no: compara tensión, corriente, alimentación o caudal de ambos bancos. Selecciona todas las causas.';}render();};}button('Volver a la revisión',()=>{retry=null;render();});}
function renderArchive(){let host=document.querySelector('#examHistory');if(!host){host=document.createElement('section');host.id='examHistory';panel.before(host);}host.replaceChildren();const add=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;};add('h2','Historial de exámenes');add('p','Hasta 50 exámenes completos en este navegador. Se recupera el último examen disponible de la versión anterior; los antiguos sobrescritos no pueden reconstruirse. Las notas pueden corresponder a dificultades diferentes.');if(archive.warning())add('p',archive.warning());const rows=archive.all();if(!rows.length){add('p','Completa un examen para comenzar tu historial.');return;}for(const [i,e]of [...rows].reverse().entries()){const score=energyExamScore(e),previous=rows[rows.length-i-2];add('p',new Date(e.finishedAt).toLocaleString('es-CO')+' · '+score+'/100 · '+e.cases.filter((c,j)=>!examCorrect(c,e.answers[j])).length+' casos fallados'+(previous?' · Cambio: '+(score-energyExamScore(previous))+' puntos':''));add('p',e.cases.map(c=>names[c.lab]+': '+({basic:'básico',combined:'combinado',intermittent:'intermitente'}[c.level])).join(' · '));const bar=add('meter','');bar.max=100;bar.value=score;bar.setAttribute('aria-label','Nota '+score+' de 100');const b=add('button','Revisar este examen');b.dataset.archiveId=e.id;b.onclick=()=>{retry=null;repair=null;inspected=e;view(0);};}add('h3','Qué averías vas consolidando');add('p','Últimas cinco respuestas relevantes por causa. Se requieren tres exámenes para indicar consistencia; no certifica dominio. Se cuentan causas presentes y falsas identificaciones, no aciertos por omisión.');for(const m of energyMastery(rows))add('p',m.label+' · '+m.correct+'/'+m.recent+' recientes correctas · '+m.errors+' errores acumulados · '+m.status);}
function finish(){finishEnergyExam(exam,results);spacing.sync(results.all());archive.add(exam);persist();view(0);}
if(exam?.status==='finished'){archive.add(exam);finishEnergyExam(exam,results);spacing.sync(results.all());view(0);}else if(exam?.answers.length===3)finish();else if(exam)view(exam.answers.length);else render();
window.energyExamDebug=()=>({exam,ready,selected,reviewRepaired,inspected,retry,repair});
